using EventLensAI.Application.Interfaces.Persistence;using EventLensAI.Domain.Entities;using EventLensAI.Infrastructure.Persistence;using Microsoft.EntityFrameworkCore;
namespace EventLensAI.Infrastructure.Repositories;
internal sealed class BrandingRepository(EventLensDbContext db):IBrandingRepository{public Task<BrandKit?>GetKitAsync(Guid o,CancellationToken ct)=>db.BrandKits.FirstOrDefaultAsync(x=>x.OrganizationId==o,ct);public Task AddKitAsync(BrandKit x,CancellationToken ct)=>db.BrandKits.AddAsync(x,ct).AsTask();public async Task<IReadOnlyList<BrandAsset>>ListAssetsAsync(Guid o,CancellationToken ct)=>await db.BrandAssets.AsNoTracking().Where(x=>x.OrganizationId==o).OrderByDescending(x=>x.CreatedAt).ToListAsync(ct);public Task<BrandAsset?>GetAssetAsync(Guid id,CancellationToken ct)=>db.BrandAssets.FirstOrDefaultAsync(x=>x.Id==id,ct);public Task AddAssetAsync(BrandAsset x,CancellationToken ct)=>db.BrandAssets.AddAsync(x,ct).AsTask();public async Task<IReadOnlyList<BrandTheme>>ListThemesAsync(Guid o,CancellationToken ct)=>await db.BrandThemes.Where(x=>x.OrganizationId==o).OrderByDescending(x=>x.IsActive).ThenBy(x=>x.Name).ToListAsync(ct);public Task<BrandTheme?>GetThemeAsync(Guid id,CancellationToken ct)=>db.BrandThemes.FirstOrDefaultAsync(x=>x.Id==id,ct);public Task<bool>ThemeNameExistsAsync(Guid o,string n,Guid?e,CancellationToken ct)=>db.BrandThemes.AnyAsync(x=>x.OrganizationId==o&&x.Name==n&&(!e.HasValue||x.Id!=e),ct);public Task AddThemeAsync(BrandTheme x,CancellationToken ct)=>db.BrandThemes.AddAsync(x,ct).AsTask();}
